use split_decls_genesis :: ourprelude :: * ; use std :: io :: Write ; use std :: path :: { Path , PathBuf } ; use super :: ResultCache ; #[doc = " Saves a reduced file for a given `stage`"] fn save_reduction (lines : & [String] , path : & Path , stage : & str) { let mut path = path . to_path_buf () ; path . set_extension (format ! ("rs.{stage}")) ; let mut file = std :: fs :: File :: create (& path) . expect ("Could not create the reduced example file") ; for line in lines { file . write_all (line . as_bytes ()) . expect ("Could not save the reduced example") ; } } #[doc = " Checks if a given reduction is valid."] fn test_reduction (lines : & [String] , path : & Path , cache : & mut ResultCache) -> bool { let mut path = path . to_path_buf () ; path . set_extension ("rs_reduced") ; let mut file = std :: fs :: File :: create (& path) . expect ("Could not create the reduced example file") ; for line in lines { file . write_all (line . as_bytes ()) . expect ("Could not save the reduced example") ; } let res = super :: test_cached (& path , false , cache) ; let Ok (Err (_)) = res else { return false ; } ; true } #[doc = " Removes duplicate assignments in bulk."] #[doc = " If a line A = B is followed directly by A = C,"] #[doc = " then removing the first line ought to be fully sound,"] #[doc = " and not change the behaviour of the program at all. Detect & remove such lines."] fn remove_dup_assign (file : & mut Vec < String > , path : & PathBuf , starts : usize , ends : usize , cache : & mut ResultCache ,) { let mut file_copy = file . clone () ; let mut reduction_count = 0 ; if ends - starts < 8 { return ; } for index in starts .. ends { let Some ((prefix , _)) = file_copy [index] . split_once ('=') else { continue ; } ; let Some ((prefix2 , postifx2)) = file_copy [index + 1] . split_once ('=') else { continue ; } ; let prefix = prefix . trim () ; let prefix2 = prefix2 . trim () ; if prefix == prefix2 && ! postifx2 . contains (prefix) { file_copy [index] = "" . into () ; reduction_count += 1 ; } } if reduction_count == 0 { return ; } if test_reduction (& file_copy , path , cache) { println ! ("Reduced {path:?} by {reduction_count} lines `remove_dup_assign`") ; * file = file_copy ; } else { remove_dup_assign (file , path , starts , (starts + ends) / 2 , cache) ; remove_dup_assign (file , path , (starts + ends) / 2 , ends , cache) ; } save_reduction (file , path , "remove_dup_assign") ; } #[doc = " Removes all the unneeded calls to `dump_var`. This is not something tools like `cvise` can do,"] #[doc = " but it greately speeds up MIR interpretation + native execution."] fn remove_dump_var (file : & mut Vec < String > , path : & PathBuf) { let mut curr = 0 ; while curr < file . len () { let Some (line) = file [curr ..] . iter () . position (| line | line . contains ("dump_var")) else { break ; } ; let line = line + curr ; let mut file_copy = file . clone () ; file_copy . remove (line) ; file_copy . remove (line) ; file_copy . remove (line) ; let mut uncached = None ; if test_reduction (& file_copy , path , & mut uncached) { println ! ("Reduced {path:?} by 3 lines `remove_dump_var`") ; * file = file_copy ; curr = line ; } else { curr = line + 1 ; } } save_reduction (file , path , "remove_dump_var") ; } #[doc = " Replaces matches with gotos where possible."] #[doc = " This exploits some properties of rustlantis(match arm order),"] #[doc = " and is only soundly applicable to MIR generated by it."] #[doc = " Still, it is not something `cvise` can do, but it simplifies the code a ton."] fn match_to_goto (file : & mut Vec < String > , path : & PathBuf , cache : & mut ResultCache) { let mut curr = 0 ; while curr < file . len () { let Some (match_starts) = file [curr ..] . iter () . position (| line | line . contains ("match")) else { break ; } ; let match_starts = match_starts + curr ; let Some (match_ends) = file [match_starts ..] . iter () . position (| line | line . contains ('}')) else { break ; } ; let match_ends = match_ends + match_starts ; let match_body = & file [match_starts .. match_ends] ; let jumps_to = & match_body [match_body . len () - 2] . trim () ; let Some ((_ , bb_ident)) = jumps_to . split_once ("bb") else { break ; } ; let bb_ident = bb_ident . trim_matches (',') ; let mut file_copy = file . clone () ; for _ in match_starts .. (match_ends + 1) { file_copy . remove (match_starts) ; } file_copy . insert (match_starts , format ! ("Goto(bb{bb_ident})\n")) ; if test_reduction (& file_copy , path , cache) { println ! ("Reduced {path:?} by {} lines `match_to_goto`" , match_ends - match_starts) ; * file = file_copy ; curr = match_starts ; } else { curr = match_ends ; } } save_reduction (file , path , "match_to_goto") ; } #[doc = " At this point, we can try \"killing\" blocks, by replacing their bodies with calls to `abort`."] #[doc = " This is always sound(the program aborts, so no UB can occur after the block),"] #[doc = " and allows us to safely remove *a lot* of unneeded blocks."] fn block_abort (file : & mut Vec < String > , path : & PathBuf , cache : & mut ResultCache) { let mut curr = 0 ; while curr < file . len () { let Some (block_starts) = file [curr ..] . iter () . position (| line | line . starts_with ("bb") && line . trim_end () . ends_with (" = {")) else { break ; } ; let block_starts = block_starts + curr ; let Some (block_ends) = file [(block_starts + 1) ..] . iter () . position (| line | line . starts_with ("bb") && line . trim_end () . ends_with (" = {")) else { break ; } ; let block_ends = block_starts + block_ends ; let block_starts = block_starts + 1 ; let mut file_copy = file . clone () ; for _ in block_starts .. (block_ends) { file_copy . remove (block_starts) ; } file_copy . insert (block_starts , "Call(tmp = core::intrinsics::abort(), ReturnTo(bb1), UnwindUnreachable())\n" . to_string () ,) ; file_copy . insert (block_starts , "let tmp = ();\n" . to_string ()) ; if test_reduction (& file_copy , path , cache) { println ! ("Reduced {path:?} by {} lines `block_abort`" , block_ends - block_starts - 2) ; * file = file_copy ; curr = block_starts ; } else { curr = block_ends ; } } save_reduction (file , path , "block_abort") ; } #[doc = " Removes unreachable basic blocks"] fn remove_block (file : & mut Vec < String > , path : & PathBuf , cache : & mut ResultCache) { let mut curr = 0 ; while curr < file . len () { let Some (block_starts) = file [curr ..] . iter () . position (| line | line . starts_with ("bb") && line . trim_end () . ends_with (" = {")) else { break ; } ; let block_starts = block_starts + curr ; let Some (block_ends) = file [(block_starts + 1) ..] . iter () . position (| line | line . starts_with ("bb") && line . trim_end () . ends_with (" = {")) else { break ; } ; let block_ends = block_starts + block_ends + 1 ; if block_ends - block_starts > 6 { curr = block_starts + 1 ; continue ; } let mut file_copy = file . clone () ; file_copy . drain (block_starts .. block_ends) ; if test_reduction (& file_copy , path , cache) { println ! ("Reduced {path:?} by {} lines `remove_blocks`" , block_ends - block_starts) ; * file = file_copy ; curr = block_starts ; } else { curr = block_starts + 1 ; } } save_reduction (file , path , "remove_block") ; } #[doc = " Merges blocks ending with unconditional jumps."] fn linearize_cf (file : & mut Vec < String > , path : & PathBuf , cache : & mut ResultCache) { let mut curr = 0 ; while curr < file . len () { let Some (block_starts) = file [curr ..] . iter () . position (| line | line . starts_with ("bb") && line . trim_end () . ends_with (" = {")) else { break ; } ; let block_starts = block_starts + curr ; let Some ((block , _)) = file [block_starts] . split_once ('=') else { curr = block_starts + 1 ; continue ; } ; let block = block . trim () ; if file [block_starts - 2] . trim () != format ! ("Goto({block})") { curr = block_starts + 1 ; continue ; } let mut file_copy = file . clone () ; file_copy . remove (block_starts - 2) ; file_copy . remove (block_starts - 2) ; file_copy . remove (block_starts - 2) ; if test_reduction (& file_copy , path , cache) { println ! ("Reduced {path:?} by 3 lines `linearize_cf`") ; * file = file_copy ; curr = block_starts ; } else { curr = block_starts + 1 ; } } save_reduction (file , path , "linearize_cf") ; } #[doc = " Replaces a call to a given function with a 0 assignment to the destination place, and a Goto."] #[doc = " This is always sound, because:"] #[doc = " 1. All the functions arguments are always initialized"] #[doc = " 2. and point to initialized  memory(the operand of &raw must be an initialized place in rustlantis)."] fn remove_fn_calls (file : & mut Vec < String > , path : & PathBuf , cache : & mut ResultCache) { let mut curr = 0 ; while curr < file . len () { let Some (fn_call) = file [curr ..] . iter () . position (| line | line . contains ("Call(") && line . contains (" = fn")) else { break ; } ; let fn_call = fn_call + curr ; let line = file [fn_call] . trim () ; let line = & line ["Call(" . len () ..] ; let Some ((place , line)) = line . split_once ('=') else { curr = fn_call + 1 ; continue ; } ; let Some ((_ , line)) = line . split_once ("ReturnTo(") else { curr = fn_call + 1 ; continue ; } ; let Some ((block , _)) = line . split_once (')') else { curr = fn_call + 1 ; continue ; } ; let mut file_copy = file . clone () ; file_copy . remove (fn_call) ; file_copy . insert (fn_call , format ! ("Goto({block})\n")) ; file_copy . insert (fn_call , format ! ("{place} = 0;\n")) ; if test_reduction (& file_copy , path , cache) { println ! ("Reduced {path:?} using `remove_fn_calls` {cache:?}") ; * file = file_copy ; curr = fn_call ; } else { curr = fn_call + 1 ; } } save_reduction (file , path , "remove_fn_calls") ; } #[doc = " Fully removes unreachable functions."] fn remove_fns (file : & mut Vec < String > , path : & PathBuf , cache : & mut ResultCache) { let mut curr = 0 ; while curr < file . len () { let Some (fn_start) = file [curr ..] . iter () . position (| line | { line . contains ("#[custom_mir(dialect = \"runtime\", phase = \"initial\")]") }) else { break ; } ; let fn_start = fn_start + curr ; let Some (fn_end) = file [(fn_start + 3) ..] . iter () . position (| line | line . contains ("fn fn")) else { break ; } ; let fn_end = fn_start + 2 + fn_end ; let mut file_copy = file . clone () ; file_copy . drain (fn_start .. fn_end) ; if test_reduction (& file_copy , path , cache) { println ! ("Reduced {path:?} by {} lines `remove_fns`" , fn_end - fn_start) ; * file = file_copy ; } else { curr = fn_start + 1 ; } } save_reduction (file , path , "remove_fns") ; } pub (super) fn reduce (path : impl AsRef < Path >) { let path = path . as_ref () . to_owned () ; let file = std :: fs :: read_to_string (& path) . expect ("Could not open the file to reduce") ; let mut file : Vec < _ > = file . split_inclusive ('\n') . map (| s | s . to_string ()) . collect () ; println ! ("running `remove_dump_var` on {path:?}.") ; remove_dump_var (& mut file , & path) ; let mut cache = None ; assert ! (test_reduction (& file , & path , & mut cache) , "Reduction error: check that the input file is a valid reproducer.") ; println ! ("cache:{cache:?}") ; println ! ("running `remove_fn_calls` on {path:?}.") ; remove_fn_calls (& mut file , & path , & mut cache) ; println ! ("running `remove_fns` on {path:?}.") ; remove_fns (& mut file , & path , & mut cache) ; let len = file . len () ; println ! ("running `remove_dup_assign` on {path:?}.") ; remove_dup_assign (& mut file , & path , 0 , len , & mut cache) ; file . retain (| line | ! line . is_empty ()) ; println ! ("running `match_to_goto` on {path:?}.") ; match_to_goto (& mut file , & path , & mut cache) ; println ! ("running `block_abort` on {path:?}.") ; block_abort (& mut file , & path , & mut cache) ; println ! ("running `remove_block` on {path:?}.") ; remove_block (& mut file , & path , & mut cache) ; println ! ("running `linearize_cf` on {path:?}.") ; linearize_cf (& mut file , & path , & mut cache) ; let mut out = std :: fs :: File :: create (& path) . expect ("Could not save the reduction result.") ; let file = file . into_iter () . collect :: < String > () ; out . write_all (file . as_bytes ()) . expect ("failed to write into file") ; }